class CoCoMESystem_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find a store with provided store id,
   *if the store exists and not open,
   *the current store is the store,
   *and the store is opened*/
  openStore(storeID: number): boolean {
    /*Definition Start*/
    let store: Store = l({
      logic: () =>
        getRepository(Store).find(
          (s: any) =>
            l({
              logic: () => s.Name === storeID,
              description: "s.Name=storeID",
            })
              .and({
                logic: () => StandardOPs.oclIsTypeOf(s, Store),
                description: "s.oclIsTypeOf(Store)",
              })
              .build().pass,
        ),
      description:
        "Store.allInstance()->any(s|s.Name=storeIDands.oclIsTypeOf(Store))",
    }).build().pass;
    let isOpened: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => store.IsOpened,
            description: "store.IsOpened",
          }),
        description: "store.IsOpened",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => getRepository(Store).includes(store),
        description: "Store.allInstance()->includes(store)",
      })
        .and({
          logic: () => isOpened === false,
          description: "isOpened=false",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (this.CurrentStore = store),
      description: "CurrentStore=store",
    })
      .and({
        execute: () => (store.IsOpened = true),
        description: "store.IsOpened=true",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { CoCoMESystem_AutoGenerated };

